def transform(grid):
    """Repeat the observed diagonal color sequence across the grid."""
    h, w = len(grid), len(grid[0])
    # Infer a periodic sequence of colors indexed by diagonal offset c-r.
    known = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                d = c - r
                if d in known and known[d] != v:
                    raise ValueError('conflicting diagonal colors')
                known[d] = v
    # Find the smallest period compatible with all observed stripe colors.
    period = None
    for p in range(1, h + w + 1):
        if all(known[a] == known[b] for a in known for b in known if (a-b) % p == 0):
            period = p
            break
    if period is None:
        period = h + w
    # Each residue gets a known color, with remaining residues interpolated
    # by nearest observed diagonal in the periodic sequence.
    residue_color = {}
    for d, v in known.items():
        residue_color[d % period] = v
    out = [[0] * w for _ in range(h)]
    anchors = list(residue_color.items())
    for r in range(h):
        for c in range(w):
            d = c-r
            k = d % period
            if k in residue_color:
                out[r][c] = residue_color[k]
            else:
                # nearest anchored residue, circularly
                dist, color = min((min((k-a) % period, (a-k) % period), v) for a,v in anchors)
                out[r][c] = color
    return out
